def get_adts_frames(data):
    frames = []
    i = 0
    while i < len(data) - 7:
        if data[i] == 0xFF and (data[i+1] & 0xF0) == 0xF0:
            frame_len = ((data[i+3] & 3) << 11) | (data[i+4] << 3) | ((data[i+5] >> 5) & 7)
