"""
Hybrid Internet Radio Server (Live Broadcast + Recorded Audio AutoDJ)
Features:
- Live Broadcasting: Ingests audio from phone/PC (BUTT, Mixxx, BroadcastMySelf).
- FFmpeg Stream Cleaner: Demuxes and normalizes live input to standard 128kbps MP3 frames.
- AutoDJ Fallback: Loops recorded MP3 files from the `audio/` folder when not live.
- Seamless Auto-Switch: Automatically switches to Live when DJ connects, and back to playlist when DJ stops.
- Web Player: Modern HTML5 player with live status indicator.
- Internet Radio Link: Permanent `/radio.mp3` stream for Choyong LC90 and other devices.
"""

import os
import glob
import subprocess
import threading
import queue
import time
import socket
import base64
import json
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

PORT = int(os.environ.get("PORT", 8080))
SOURCE_PASSWORD = os.environ.get("SOURCE_PASSWORD", "myradiopassword")
STATION_NAME = os.environ.get("STATION_NAME", "My Online Radio")

AUDIO_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "audio")
os.makedirs(AUDIO_DIR, exist_ok=True)

# State
is_live = False
current_track = "Station Playlist"
state_lock = threading.Lock()

# Master broadcast queues for listeners
listener_queues = []
listeners_lock = threading.Lock()
rolling_buffer = bytearray()
buffer_lock = threading.Lock()

def broadcast_audio(chunk):
    """Pushes audio chunk to all connected listeners."""
    global rolling_buffer
    if not chunk:
        return
    with buffer_lock:
        rolling_buffer.extend(chunk)
        if len(rolling_buffer) > 64 * 1024:
            rolling_buffer = rolling_buffer[-64*1024:]

    with listeners_lock:
        for q in list(listener_queues):
            try:
                q.put_nowait(chunk)
            except queue.Full:
                try:
                    q.get_nowait()
                    q.put_nowait(chunk)
                except Exception:
                    pass

def autodj_worker():
    """Loops through recorded audio files when not in live mode."""
    global current_track
    print("[*] AutoDJ engine initialized.", flush=True)

    while True:
        if is_live:
            time.sleep(0.5)
            continue

        audio_files = []
        for ext in ("*.mp3", "*.wav", "*.m4a", "*.aac", "*.ogg"):
            audio_files.extend(glob.glob(os.path.join(AUDIO_DIR, ext)))

        if not audio_files:
            time.sleep(1.0)
            continue

        audio_files.sort()

        for track_path in audio_files:
            if is_live:
                break

            track_name = os.path.basename(track_path)
            with state_lock:
                if not is_live:
                    current_track = track_name
            print(f"[AutoDJ] Playing: {track_name}", flush=True)

            cmd = [
                "ffmpeg",
                "-re",
                "-i", track_path,
                "-vn",
                "-c:a", "libmp3lame",
                "-b:a", "128k",
                "-ar", "44100",
                "-ac", "2",
                "-f", "mp3",
                "pipe:1"
            ]

            try:
                proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, bufsize=1024*32)
                while True:
                    if is_live:
                        proc.terminate()
                        break
                    chunk = proc.stdout.read(2048)
                    if not chunk:
                        break
                    broadcast_audio(chunk)
                proc.wait()
            except Exception as e:
                print(f"[AutoDJ Error] {e}", flush=True)
                time.sleep(1.0)

