class RadioServerHandler(BaseHTTPRequestHandler):
    def do_AUTH(self):
        """Authenticates live broadcaster."""
        auth_header = self.headers.get("Authorization", "")
        ice_pwd = self.headers.get("ice-password", "")

        if ice_pwd == SOURCE_PASSWORD:
            return True
        if auth_header.startswith("Basic "):
            try:
                decoded = base64.b64decode(auth_header[6:]).decode("utf-8")
                pwd = decoded.split(":")[-1]
                if pwd == SOURCE_PASSWORD:
                    return True
            except Exception:
                pass
        return False

    def handle_live_source(self):
        """Receives live broadcast stream and runs through FFmpeg stream normalizer."""
        global is_live, current_track
        if not self.do_AUTH():
            self.send_response(401)
            self.send_header("WWW-Authenticate", 'Basic realm="Live Broadcast Source"')
            self.end_headers()
            self.wfile.write(b"Unauthorized: Invalid Source Password\n")
            return

        print(f"\n[🎙️ LIVE] Broadcaster CONNECTED from {self.client_address[0]}!", flush=True)
        with state_lock:
            is_live = True
            current_track = "🔴 LIVE BROADCAST"

        self.send_response(200)
        self.send_header("Connection", "keep-alive")
        self.end_headers()

        # Launch FFmpeg to normalize and clean up live audio stream
        cleaner_cmd = [
            "ffmpeg",
            "-i", "pipe:0",
            "-vn",
            "-c:a", "libmp3lame",
            "-b:a", "128k",
            "-ar", "44100",
            "-ac", "2",
            "-f", "mp3",
            "pipe:1"
        ]

        try:
            cleaner = subprocess.Popen(
                cleaner_cmd,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                bufsize=1024 * 32
            )

            def pump_live_output():
                while is_live:
                    out_chunk = cleaner.stdout.read(2048)
                    if not out_chunk:
                        break
                    broadcast_audio(out_chunk)

            out_thread = threading.Thread(target=pump_live_output, daemon=True)
            out_thread.start()

            # Pipe incoming socket stream into FFmpeg
            while True:
                chunk = self.rfile.read(2048)
                if not chunk:
                    break
                try:
                    cleaner.stdin.write(chunk)
                    cleaner.stdin.flush()
                except Exception:
                    break

            cleaner.terminate()
        except Exception as e:
            print(f"[!] Live stream processing error: {e}", flush=True)
        finally:
            print(f"[🎙️ LIVE] Broadcaster DISCONNECTED: {self.client_address[0]}.", flush=True)
            with state_lock:
                is_live = False
                current_track = "Station Playlist"

    def do_SOURCE(self):
        self.handle_live_source()

    def do_PUT(self):
        self.handle_live_source()

    def do_POST(self):
        self.handle_live_source()

    def do_GET(self):
        if self.path in ("/healthz", "/health"):
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.end_headers()
            self.wfile.write(b"OK")
            return

        if self.path == "/status":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            with state_lock:
                data = {
                    "station": STATION_NAME,
                    "is_live": is_live,
                    "track": current_track,
                    "listeners": len(listener_queues)
                }
            self.wfile.write(json.dumps(data).encode("utf-8"))
            return

        if self.path in ("/", "/index.html"):
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(INDEX_HTML.encode("utf-8"))
            return

        if self.path.startswith("/radio.mp3") or self.path.startswith("/stream") or self.path.startswith("/live.mp3"):
            print(f"[+] Listener connected from {self.client_address[0]}", flush=True)
            self.send_response(200)
            self.send_header("Content-Type", "audio/mpeg")
            self.send_header("Cache-Control", "no-cache, no-store, must-revalidate")
            self.send_header("Pragma", "no-cache")
            self.send_header("Expires", "0")
            self.send_header("Connection", "keep-alive")
            self.send_header("icy-name", STATION_NAME)
            self.send_header("icy-br", "128")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()

            client_q = queue.Queue(maxsize=100)

            with buffer_lock:
                if rolling_buffer:
                    client_q.put(bytes(rolling_buffer))

            with listeners_lock:
                listener_queues.append(client_q)

            try:
                while True:
                    try:
                        chunk = client_q.get(timeout=10)
                        self.wfile.write(chunk)
                        self.wfile.flush()
                    except queue.Empty:
                        pass
            except (BrokenPipeError, ConnectionResetError, socket.error):
                pass
            finally:
                with listeners_lock:
                    if client_q in listener_queues:
                        listener_queues.remove(client_q)
                print(f"[-] Listener disconnected: {self.client_address[0]}", flush=True)
            return

        self.send_error(404)

    def log_message(self, format, *args):
        return

