class RadioServerHandler(BaseHTTPRequestHandler):
    def do_AUTH(self):
        auth_header = self.headers.get("Authorization", "")
        ice_pwd = self.headers.get("ice-password", "")

        if ice_pwd == SOURCE_PASSWORD:
            return True
        if auth_header.startswith("Basic "):
            try:
                decoded = base64.b64decode(auth_header[6:]).decode("utf-8")
                pwd = decoded.split(":")[-1]
                if pwd == SOURCE_PASSWORD:
                    return True
            except Exception:
                pass
        return False

    def handle_live_source(self):
        """Demuxes chunked/raw HTTP stream and broadcasts pure MP3 audio frames."""
        global is_live, current_track
        if not self.do_AUTH():
            self.send_response(401)
            self.send_header("WWW-Authenticate", 'Basic realm="Live Broadcast Source"')
            self.end_headers()
            self.wfile.write(b"Unauthorized: Invalid Source Password\n")
            return

        print(f"\n[🎙️ LIVE] Broadcaster CONNECTED from {self.client_address[0]}!", flush=True)
        with state_lock:
            is_live = True
            current_track = "🔴 LIVE BROADCAST"

        self.send_response(200)
        self.send_header("Connection", "keep-alive")
        self.end_headers()

        is_chunked = "chunked" in self.headers.get("Transfer-Encoding", "").lower()

        try:
            if is_chunked:
                # HTTP/1.1 Chunked Transfer Decoder
                while True:
                    line = self.rfile.readline()
                    if not line:
                        break
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        chunk_len = int(line.split(b";")[0], 16)
                    except ValueError:
                        break
                    if chunk_len == 0:
                        break
                    data = self.rfile.read(chunk_len)
                    self.rfile.read(2)  # skip trailing CRLF
                    if data:
                        broadcast_audio(data)
            else:
                # Direct streaming upload
                while True:
                    chunk = self.rfile.read(1024)
                    if not chunk:
                        break
                    broadcast_audio(chunk)
        except Exception as e:
            print(f"[!] Live stream ended: {e}", flush=True)
        finally:
            print(f"[🎙️ LIVE] Broadcaster DISCONNECTED: {self.client_address[0]}.", flush=True)
            with state_lock:
