class RadioServerHandler(BaseHTTPRequestHandler):
    def do_AUTH(self):
        auth_header = self.headers.get("Authorization", "")
        ice_pwd = self.headers.get("ice-password", "")

        if ice_pwd == SOURCE_PASSWORD:
            return True
        if auth_header.startswith("Basic "):
            try:
                decoded = base64.b64decode(auth_header[6:]).decode("utf-8")
                pwd = decoded.split(":")[-1]
                if pwd == SOURCE_PASSWORD:
                    return True
            except Exception:
                pass
        return False

    def handle_live_source(self):
        """Proxy-tolerant live broadcast ingest with 15s timeout."""
        global is_live, current_track
        if not self.do_AUTH():
            self.send_response(401)
            self.send_header("WWW-Authenticate", 'Basic realm="Live Broadcast Source"')
            self.end_headers()
            self.wfile.write(b"Unauthorized: Invalid Source Password\n")
            return

        print(f"\n[🎙️ LIVE] Broadcaster CONNECTED from {self.client_address[0]}!", flush=True)
        with state_lock:
            is_live = True
            current_track = "🔴 LIVE BROADCAST"

        # Send Icecast 100 Continue
        try:
            self.wfile.write(b"HTTP/1.0 100 Continue\r\n\r\n")
            self.wfile.flush()
        except Exception:
            pass

        self.connection.settimeout(15.0)
        sock = self.connection

        try:
            while True:
                try:
                    chunk = sock.recv(2048)
                    if not chunk:
                        print("[!] Broadcaster disconnected.", flush=True)
                        break
                    broadcast_audio(chunk)
                except socket.timeout:
                    print("[!] Live stream timeout (15s idle). Resetting to playlist.", flush=True)
                    break
        except Exception as e:
            print(f"[!] Live stream ended: {e}", flush=True)
        finally:
            print(f"[🎙️ LIVE] Broadcaster DISCONNECTED: {self.client_address[0]}.", flush=True)
            with state_lock:
                is_live = False
                current_track = "welcome_jingle.mp3"

    def do_SOURCE(self):
        self.handle_live_source()

    def do_PUT(self):
        self.handle_live_source()

    def do_POST(self):
        self.handle_live_source()

    def do_GET(self):
        if self.path in ("/healthz", "/health"):
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.end_headers()
            self.wfile.write(b"OK")
            return

        if self.path == "/favicon.ico":
            self.send_response(204)
            self.end_headers()
            return

        if self.path == "/status":
            self.send_response(200)
