def broadcast_audio(chunk):
    """Pushes audio chunk to all connected listeners."""
    global rolling_buffer
    if not chunk:
        return
    with buffer_lock:
        rolling_buffer.extend(chunk)
        if len(rolling_buffer) > 64 * 1024:
            rolling_buffer = rolling_buffer[-64*1024:]

    with listeners_lock:
        for q in list(listener_queues):
            try:
                q.put_nowait(chunk)
            except queue.Full:
                try:
                    q.get_nowait()
                    q.put_nowait(chunk)
                except Exception:
                    pass

def autodj_worker():
    """Uninterrupted continuous MP3 streaming engine with precise 128kbps rate clock."""
    global current_track
    print("[*] Continuous AutoDJ engine active.", flush=True)

    CHUNK_SIZE = 2000
    CHUNK_DELAY = CHUNK_SIZE / 16000.0  # 128 kbps = 16,000 bytes/sec -> 0.125s per chunk

    while True:
        if is_live:
            time.sleep(0.2)
            continue

        mp3_files = sorted(glob.glob(os.path.join(AUDIO_DIR, "*.mp3")))
        if not mp3_files:
            time.sleep(1.0)
            continue

        for track_path in mp3_files:
            if is_live:
                break

            track_name = os.path.basename(track_path)
            with state_lock:
                if not is_live:
                    current_track = track_name

            try:
                with open(track_path, "rb") as f:
                    while not is_live:
                        chunk = f.read(CHUNK_SIZE)
                        if not chunk:
                            break
                        broadcast_audio(chunk)
                        time.sleep(CHUNK_DELAY)
            except Exception as e:
                print(f"[AutoDJ Error] {e}", flush=True)
                time.sleep(0.5)

